#include <gvpe/gvpe_particle.h>

GvpeWorld* world = gvpe_world_create();
GvpeParticleDesc desc = {
    .emitter_type  = GVPE_EMITTER_SPHERE,
    .radius        = 1.0f,
    .max_particles = 1000,
    .lifetime      = 5.0f  // 5 秒
};

GvpeParticleHandle ps = gvpe_particle_create(world, &desc);
if (ps == NULL) {
    fprintf(stderr, "failed to create particle system\n");
    return -1;
}

// 使用完毕后销毁
gvpe_particle_destroy(ps);
